($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17196212, $f$What E'er Drifts From One Place is With the Tide to Another Brought$f$, ARRAY[$f$SpaceguyLewis$f$]::text[], ARRAY[$f$Dishonored (Video Games)$f$]::text[], NULL, ARRAY[]::text[], $f$There will always be those who wish to bend the Void to their will, and there is more than one way to make a god.$f$, 5844, 2, 2, true, 1, false, $f$2019-06-30T15:56:16.330+00:00$f$, $f$2019-06-30T15:56:16.625+00:00$f$, $f$2018-12-29T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17202818, $f$целуй меня в левую бровь$f$, ARRAY[$f$Marlan$f$]::text[], ARRAY[$f$魔道祖师 - 墨香铜臭 | Módào Zǔshī - Mòxiāng Tóngxiù$f$]::text[], NULL, ARRAY[]::text[], $f$не уходи$f$, 1439, 1, 1, true, -1, false, $f$2019-10-30T11:55:17.998+00:00$f$, $f$2019-10-30T11:55:18.026+00:00$f$, $f$2018-12-28T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17208188, $f$Eyes Like Marbles$f$, ARRAY[$f$SpaceguyLewis$f$]::text[], ARRAY[$f$Dishonored (Video Games)$f$]::text[], NULL, ARRAY[]::text[], $f$“What now, Outsider?”It was as much an inquiry about what he would do with tomorrow as the rest of his mortal life.The Outsider's journey as a mortal from Shindaerey Peak to the Tower of Dunwall, in pursuit of Corvo Attano.$f$, 13771, 3, NULL, false, 1, false, $f$2019-06-30T15:58:52.295+00:00$f$, $f$2019-06-30T15:58:52.382+00:00$f$, $f$2019-02-03T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
