($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17211965, $f$Until We Kiss Again$f$, ARRAY[$f$adrift_me$f$]::text[], ARRAY[$f$Dishonored (Video Games)$f$]::text[], NULL, ARRAY[]::text[], $f$Yuletide is the time for festivities and surprise kisses under the mistletoe; for Corvo they are caused by a mischievous deity that likes his kisses greatly.$f$, 753, 1, 1, true, 3, false, $f$2019-07-13T18:53:24.741+00:00$f$, $f$2019-07-13T18:53:24.783+00:00$f$, $f$2018-12-29T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17215550, $f$Another Kind of Marriage$f$, ARRAY[$f$Titans_R_Us$f$]::text[], ARRAY[$f$魔道祖师 - 墨香铜臭 | Módào Zǔshī - Mòxiāng Tóngxiù$f$]::text[], NULL, ARRAY[]::text[], $f$Wei Wuxian gets married to Lan Wangji a different way. Did you know if you pull a Lan Sect member's ribbon off you have to marry them? Everyone knows how strict the Lan Sect is about rules. Everyone.“WHO HAS A VIRGINITY RIBBON ANYWAY?”“That is not all it stands for, it also represents self-restraint, honor–”“BUT I’M TOO YOUNG TO GET MARRIED.”$f$, 1204, 1, 1, true, 1, false, $f$2019-10-26T06:11:45.644+00:00$f$, $f$2019-10-26T06:11:45.669+00:00$f$, $f$2018-12-29T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17220260, $f$make the feathers fly$f$, ARRAY[$f$Joythea$f$, $f$Naorimasa$f$]::text[], ARRAY[$f$魔道祖师 - 墨香铜臭 | Módào Zǔshī - Mòxiāng Tóngxiù$f$]::text[], NULL, ARRAY[]::text[], $f$Mo Xuanyu was sure he had performed the ritual correctly. He died and successfully summoned Wei Wuxian.So why is he still here?$f$, 69555, 12, 24, false, 1, false, $f$2019-11-10T10:42:32.144+00:00$f$, $f$2019-11-10T10:42:32.192+00:00$f$, $f$2019-10-13T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17244707, $f$The Holiness of the Heart's Affections$f$, ARRAY[$f$cassiopeiasara$f$]::text[], ARRAY[$f$Call the Midwife$f$]::text[], NULL, ARRAY[]::text[], $f$$f$, 5215, 8, 8, true, 3, false, $f$2019-06-03T02:55:56.481+00:00$f$, $f$2019-06-03T02:55:56.537+00:00$f$, $f$2018-12-31T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17247626, $f$Oblivious Honeymoon$f$, ARRAY[$f$Ziane$f$]::text[], ARRAY[$f$魔道祖师 - 墨香铜臭 | Módào Zǔshī - Mòxiāng Tóngxiù$f$, $f$The Grandmaster of Demonic Cultivation$f$, $f$Founder of Diabolism$f$]::text[], NULL, ARRAY[]::text[], $f$$f$, 26019, 4, 4, true, 1, false, $f$2019-10-30T07:41:25.863+00:00$f$, $f$2019-10-30T07:41:25.930+00:00$f$, $f$2019-01-01T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17256188, $f$focal, filler, and line$f$, ARRAY[$f$bosbie$f$]::text[], ARRAY[$f$魔道祖师 - 墨香铜臭 | Módào Zǔshī - Mòxiāng Tóngxiù$f$]::text[], NULL, ARRAY[]::text[], $f$Mo XuanYu successfully summons the Yiling Patriarch from the dead and exacts revenge on those who wronged him. A cursed arm is detained in Dafan Mountain, and the newly-revived spirit of the most hated man in the cultivation world quietly leaves the scene under his old acquaintances’ noses.Three years later, someone — a lunatic to some, a dead man to others — sells flowers at the marketplace in the dead of winter.$f$, 20016, 9, NULL, false, -1, false, $f$2019-10-23T13:30:07.780+00:00$f$, $f$2019-10-23T13:30:07.809+00:00$f$, $f$2019-08-04T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17263784, $f$Good Days$f$, ARRAY[$f$darkbrokenreaper$f$]::text[], ARRAY[$f$魔道祖师 - 墨香铜臭 | Módào Zǔshī - Mòxiāng Tóngxiù$f$]::text[], NULL, ARRAY[]::text[], $f$Lan Yuan loves good days. He spends the whole day with his mother and father and it is filled with warmth and laughter. Lan Yuan absolutely loves good days. But just as there are good days, there are also bad days.Also: What would have happened if  Lan Wangji had not taken "no" as an answer when he asked Wei Ying to come back to Gusu with him.$f$, 9143, 3, 3, true, -1, false, $f$2019-10-25T10:32:04.053+00:00$f$, $f$2019-10-25T10:32:04.077+00:00$f$, $f$2019-08-19T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17293682, $f$tell me the story?$f$, ARRAY[$f$JustAnotherWriterChica$f$]::text[], ARRAY[$f$Call the Midwife$f$]::text[], NULL, ARRAY[]::text[], $f$As Lucille and Valerie’s relationship grows and progresse, Lucille comes to find that some of their most intimate moments are centered around the scars and marks she’s discovered on Valerie’s body.$f$, 8369, 1, 1, true, 1, false, $f$2019-06-04T11:47:49.637+00:00$f$, $f$2019-06-04T11:47:49.710+00:00$f$, $f$2019-01-04T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17307755, $f$the quality of mercy$f$, ARRAY[$f$spirallings$f$]::text[], ARRAY[$f$魔道祖师 - 墨香铜臭 | Módào Zǔshī - Mòxiāng Tóngxiù$f$]::text[], NULL, ARRAY[]::text[], $f$Mo Xuanyu was the village lunatic, but having observed the characters within the Yunmeng Palace, he has to wonder if he's truly the crazy one.$f$, 3531, 1, 1, true, 5, false, $f$2019-10-30T11:43:58.107+00:00$f$, $f$2019-10-30T11:43:58.147+00:00$f$, $f$2019-01-05T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
