($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17650937, $f$Hard Choices$f$, ARRAY[$f$Anonymous$f$]::text[], ARRAY[$f$Original Work$f$]::text[], NULL, ARRAY[]::text[], $f$It comes down to this: when Raphael Venneri asks you something, you don't fucking say no.$f$, 3114, 1, 1, true, 3, false, $f$2019-02-18T05:15:08.623+00:00$f$, $f$2019-02-18T05:15:08.700+00:00$f$, $f$2019-02-15T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
