($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17678948, $f$i hate the feeling$f$, ARRAY[$f$illuminasnox$f$]::text[], ARRAY[$f$魔道祖师 - 墨香铜臭 | Módào Zǔshī - Mòxiāng Tóngxiù$f$]::text[], NULL, ARRAY[]::text[], $f$their first meeting$f$, 2552, 3, NULL, false, 1, false, $f$2019-11-03T17:21:02.342+00:00$f$, $f$2019-11-03T17:21:02.368+00:00$f$, $f$2019-02-06T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17688059, $f$Sporting Behavior$f$, ARRAY[$f$anticyclone$f$]::text[], ARRAY[$f$Original Work$f$]::text[], NULL, ARRAY[]::text[], $f$Imani has not had a great few months, since the war ended. Then one of her former soldiers gets herself into a scuffle with a feather-wearing professional duelist - and is far too drunk to fight. Imani steps up as proxy, and wrangles herself an interesting invitation out of it.$f$, 2208, 1, 1, true, 5, false, $f$2025-05-04T14:01:11.493+00:00$f$, $f$2025-05-04T14:01:11.494+00:00$f$, $f$2019-02-07T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
