($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17691362, $f$A Rush and a Push and the Land is Ours$f$, ARRAY[$f$1863$f$]::text[], ARRAY[$f$Castlevania (Cartoon)$f$]::text[], NULL, ARRAY[]::text[], $f$In the end, there’s only one other person who understands what it means to be a Forgemaster.$f$, 3613, 1, 1, true, 5, false, $f$2025-04-30T20:05:24.517+00:00$f$, $f$2025-04-30T20:05:24.521+00:00$f$, $f$2019-02-21T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
