($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17700521, $f$The Latest Work$f$, ARRAY[$f$Anonymous$f$]::text[], ARRAY[$f$Star Trek: Deep Space Nine$f$]::text[], NULL, ARRAY[]::text[], $f$Garak is put in the unfortunate position of having to correct a misconception Bashir seems to have about Cardassian culture. -Garak sets his shoulders back and stares at Bashir as seriously as he can. Bashir, for his part, is looking right at Garak, half-smiling, which manages to annoy Garak even further. “I enjoy our meals together, Doctor, but If you continue your insistence on arguing with me in such a public fashion, people will begin to talk.”$f$, 1220, 1, 1, true, 3, false, $f$2019-02-16T18:09:14.584+00:00$f$, $f$2019-02-16T18:09:14.587+00:00$f$, $f$2019-02-15T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 17700581, $f$Noble Intentions$f$, ARRAY[$f$Anonymous$f$]::text[], ARRAY[$f$Original Work$f$]::text[], NULL, ARRAY[]::text[], $f$"I could leave," I thought. "She clearly doesn't want my help; I have other things to think about. I could just call it a night." But I couldn't, not really.$f$, 2431, 1, 1, true, 3, false, $f$2019-02-17T01:11:27.894+00:00$f$, $f$2019-02-17T01:11:28.210+00:00$f$, $f$2019-02-08T00:00:00.000+00:00$f$, false, false, true, NULL, NULL, ARRAY[]::text[]),
